#include <iostream>
#include <string>
#include <vector>
#include "OctiBoard.hxx"
#include "OctiBotAgent.hxx"
#include "OctiBotConfig.hxx"
#include "OctiBotEngine.hxx"
#include "OctiBotRunner.hxx"
#include "OctiDefs.hxx"
#include "OctiGame.hxx"

namespace octi {

/**
 * CustomStarterAgent illustrates how to build a custom OCTI bot agent:
 * - Reads custom configuration keys from OctiBotConfigStore.
 * - Inspects legal moves generated by OctiGame::generateLegalMoves.
 * - Simulates moves using a scratch OctiBoard.
 * - Employs a basic material and base-distance heuristic.
 */
class CustomStarterAgent : public OctiBotAgent {
public:
    void onConfigure(const OctiBotConfigStore &config) override {
        // Read custom user parameters with safe fallbacks
        _aggression = config.getDouble("custom_aggression", 1.0);
        _preferJumps = config.getBool("prefer_jumps", true);
    }

    void onConnected(const BotIdentity &identity) override {
        std::cout << "[CustomStarterAgent] Connected as " << identity.handle
                  << " (Owner: " << identity.ownerHandle << ")\n";
    }

    void onGameStarted(const GameViewData &game, int mySeat,
                       std::string &outGreetingChat) override {
        (void) game;
        (void) mySeat;
        outGreetingChat = "Hello! Best of luck.";
    }

    std::string computeMove(const OctiBoard &board,
                            const GameViewData &game,
                            int mySeat,
                            std::int64_t remainingClockMs,
                            BotMoveTelemetry *outTelemetry) override {
        (void) game;
        (void) remainingClockMs;

        if (!board.getGame()) {
            return "";
        }

        std::vector<OctiMove> legalMoves = board.getGame()->generateLegalMoves();
        if (legalMoves.empty()) {
            return "";
        }

        // Heuristic candidate evaluation
        const OctiMove *bestMove = &legalMoves.front();
        int bestScore = -999999;
        OctiPlayer myPlayer = static_cast<OctiPlayer>(mySeat);

        for (const auto &m : legalMoves) {
            int score = 0;
            std::string notation = m.asString();

            // Simulate move on a scratch board
            OctiBoard nextBoard(board.getGameMode(),
                                board.getGame()->useSuperProngs(),
                                board.getGame()->useEdgelessBoard(),
                                board.getGame()->getBases());
            nextBoard.fromPositionString(board.toPositionString());
            if (nextBoard.getGame()) {
                nextBoard.getGame()->move(m);
                if (nextBoard.getGame()->isGameOver() && nextBoard.getGame()->getWinner() == myPlayer) {
                    bestMove = &m;
                    bestScore = 100000;
                    break;
                }
                score += OctiBotEngine::evaluatePosition(nextBoard, myPlayer);
            }

            // Material and jump heuristics
            if (notation.find('x') != std::string::npos) {
                score += static_cast<int>(1500 * _aggression);
            }
            if (_preferJumps && notation.find('-') != std::string::npos) {
                score += static_cast<int>(300 * _aggression);
            }

            if (score > bestScore) {
                bestScore = score;
                bestMove = &m;
            }
        }

        if (outTelemetry) {
            outTelemetry->depthReached = 1;
            outTelemetry->nodesVisited = legalMoves.size();
            outTelemetry->evalScore = bestScore;
            outTelemetry->elapsedMs = 1;
            outTelemetry->present = true;
        }

        return bestMove->asString();
    }

private:
    double _aggression = 1.0;
    bool _preferJumps = true;
};

} // namespace octi

int main(int argc, char **argv) {
    // Register custom bot agent with the registry
    octi::OctiBotAgentRegistry::instance().registerAgent("minimal",
        [](const octi::OctiBotConfigStore &config) {
            auto agent = std::make_unique<octi::CustomStarterAgent>();
            agent->onConfigure(config);
            return agent;
        });

    return octi::runFleetCli(argc, argv);
}

